import { loadFromGitHub } from 'gowm';

// Load text processing module
const text = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
  path: 'text-wasm',
  name: 'text-wasm',
  branch: 'master'
});

// Configure for production use
text.call('setSilentMode', true);

// Text similarity analysis
const similarity = text.call('textSimilarity', 'hello world', 'hello earth');
console.log('Similarity:', similarity); // ~0.75

// String case conversions
console.log('camelCase:', text.call('camelCase', 'hello world test')); // helloWorldTest
console.log('kebab-case:', text.call('kebabCase', 'HelloWorldTest')); // hello-world-test
console.log('snake_case:', text.call('snakeCase', 'HelloWorldTest')); // hello_world_test

// URL-friendly slug
const slug = text.call('slugify', 'Héllo Wörld! Test & More');
console.log('Slug:', slug); // hello-world-test-more

// Extract information from text
const sampleText = `
  Contact us at support@example.com or admin@test.org
  Visit our website: https://example.com or https://test.org/page
  Call us: +1-555-123-4567 or (555) 987-6543
`;

// Extract emails
const emails = text.call('extractEmails', sampleText);
console.log('Emails found:', emails); // ['support@example.com', 'admin@test.org']

// Extract URLs
const urls = text.call('extractURLs', sampleText);
console.log('URLs found:', urls); // ['https://example.com', 'https://test.org/page']

// Extract phone numbers
const phones = text.call('extractPhoneNumbers', sampleText);
console.log('Phones found:', phones); // ['+1-555-123-4567', '(555) 987-6543']

// Validate email
const emailValidation = text.call('validateEmail', 'user@example.com');
if (emailValidation.valid) {
  console.log('Valid email:', emailValidation.email);
} else {
  console.error('Invalid email:', emailValidation.error);
}

// Text analysis and metrics
const article = `
  Lorem ipsum dolor sit amet, consectetur adipiscing elit. 
  Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.
  Ut enim ad minim veniam, quis nostrud exercitation ullamco.
`;

// Word and character counting
const wordCount = text.call('wordCount', article);
const charCount = text.call('characterCount', article);
console.log('Words:', wordCount); // 26
console.log('Characters:', charCount.characters); // Total characters
console.log('Characters (no spaces):', charCount.charactersNoSpaces);
console.log('Bytes:', charCount.bytes);

// Reading time estimation
const readingStats = text.call('readingTime', article, 250); // 250 WPM
console.log('Reading time:', readingStats.minutes, 'minutes');
console.log('Word count:', readingStats.words);
console.log('Reading speed:', readingStats.wpm, 'WPM');

// String distance calculation
const distance = text.call('levenshteinDistance', 'kitten', 'sitting');
console.log('Edit distance:', distance); // 3

// Advanced text processing
const accentedText = 'Café, naïve, résumé, piñata';

// Remove diacritics
const withoutAccents = text.call('removeDiacritics', accentedText);
console.log('Without accents:', withoutAccents); // Cafe, naive, resume, pinata

// Full transliteration
const transliterated = text.call('transliterate', 'Müller & Weiß');
console.log('Transliterated:', transliterated); // Muller & Weiss

// Phonetic matching with Soundex
const soundex1 = text.call('soundex', 'Smith');
const soundex2 = text.call('soundex', 'Smyth');
console.log('Soundex codes:', soundex1, soundex2); // Same code = S530

// Secure password generation
const password = text.call('generatePassword', 16, true);
console.log('Generated password:', password.password);
console.log('Length:', password.length);
console.log('Includes symbols:', password.includeSymbols);

// Comprehensive text analysis toolkit
import { loadFromGitHub } from 'gowm';

class TextAnalyzer {
  constructor() {
    this.text = null;
    this.ready = false;
    this.loadModule();
  }

  async loadModule() {
    try {
      this.text = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
        path: 'text-wasm',
              name: 'text-wasm'
      });

      // Configure for production use
      this.text.call('setSilentMode', true);

      // Get available functions
      const functions = this.text.call('getAvailableFunctions');
      console.log('Available text functions:', functions);

      this.ready = true;
    } catch (error) {
      console.error('Failed to load text module:', error);
    }
  }

  // Comprehensive text analysis
  analyzeText(inputText) {
    if (!this.ready || !inputText) {
      throw new Error('Text module not ready or no input provided');
    }

    return {
      wordCount: this.text.call('wordCount', inputText),
      charCount: this.text.call('characterCount', inputText),
      readingTime: this.text.call('readingTime', inputText),
      emails: this.text.call('extractEmails', inputText),
      urls: this.text.call('extractURLs', inputText),
      phones: this.text.call('extractPhoneNumbers', inputText),
      slug: this.text.call('slugify', inputText),
      camelCase: this.text.call('camelCase', inputText),
      kebabCase: this.text.call('kebabCase', inputText),
      snakeCase: this.text.call('snakeCase', inputText),
      withoutAccents: this.text.call('removeDiacritics', inputText),
      transliterated: this.text.call('transliterate', inputText)
    };
  }

  // String similarity analysis
  compareStrings(str1, str2) {
    if (!this.ready) throw new Error('Text module not ready');

    return {
      similarity: this.text.call('textSimilarity', str1, str2),
      levenshteinDistance: this.text.call('levenshteinDistance', str1, str2),
      soundex1: this.text.call('soundex', str1),
      soundex2: this.text.call('soundex', str2),
      soundexMatch: this.text.call('soundex', str1) === this.text.call('soundex', str2)
    };
  }

  // Security utilities
  generateSecurePassword(length = 16, includeSymbols = true) {
    if (!this.ready) throw new Error('Text module not ready');

    return this.text.call('generatePassword', length, includeSymbols);
  }

  validateEmail(email) {
    if (!this.ready) throw new Error('Text module not ready');

    return this.text.call('validateEmail', email);
  }

  // Case conversion utilities
  convertCase(text, format) {
    if (!this.ready) throw new Error('Text module not ready');

    const converters = {
      'camel': 'camelCase',
      'kebab': 'kebabCase',
      'snake': 'snakeCase',
      'slug': 'slugify'
    };

    const functionName = converters[format];
    if (!functionName) {
      throw new Error(`Unknown format: ${format}. Use: camel, kebab, snake, slug`);
    }

    return this.text.call(functionName, text);
  }
}

// Usage example
const analyzer = new TextAnalyzer();

// Wait for module to load
setTimeout(() => {
  if (analyzer.ready) {
    const sampleText = 'Hello World! Visit https://example.com or email us at contact@example.com. Call +1-555-123-4567 for support.';

    // Comprehensive analysis
    const analysis = analyzer.analyzeText(sampleText);
    console.log('Text Analysis:', {
      words: analysis.wordCount,
      characters: analysis.charCount.characters,
      readingTime: analysis.readingTime.minutes + ' minutes',
      emails: analysis.emails,
      urls: analysis.urls,
      phones: analysis.phones,
      slug: analysis.slug
    });

    // String comparison
    const comparison = analyzer.compareStrings('Smith', 'Smyth');
    console.log('String Comparison:', comparison);

    // Password generation
    const password = analyzer.generateSecurePassword(20, true);
    console.log('Generated Password:', password);

    // Case conversions
    console.log('Case Conversions:', {
      camel: analyzer.convertCase('hello world test', 'camel'),
      kebab: analyzer.convertCase('Hello World Test', 'kebab'),
      snake: analyzer.convertCase('Hello World Test', 'snake')
    });
  }
}, 1000);
